scenarioTemplate.data:
info = {
  name: "⏱️ Время присутствия дома",
  description: "Пишет в характеристику «Дистанция» (C_Distance) датчика присутствия время нахождения человека дома в формате Ч.ММ: 2.45 = 2 ч 45 мин, 0.59 = 59 мин. Привязывается к каждому человеку отдельно.",
  version: "1.1",
  author: "Andrey",
  onStart: true,

  sourceServices: [HS.OccupancySensor],
  sourceCharacteristics: [HC.OccupancyDetected],

  options: {
    resetOnLeave: {
      name: { ru: "Обнулять при уходе", en: "Reset on leave" },
      desc: { ru: "ВКЛ — при уходе Дистанция = 0. ВЫКЛ — до следующего прихода остаётся длительность последнего пребывания.", en: "ON — distance = 0 on leave. OFF — keeps last visit duration until next arrival." },
      type: "Boolean",
      value: true
    },
    logEnabled: {
      name: { ru: "Логирование событий", en: "Event logging" },
      desc: { ru: "Если включено — пишет приход/уход и восстановление после перезапуска. Ошибки пишутся всегда.", en: "If ON: arrivals/leaves are logged. Errors always." },
      type: "Boolean",
      value: false
    }
  },

  variables: {
    cron: undefined,
    start: undefined,
    lastPresence: undefined,
    lastWritten: undefined,
    label: undefined
  }
};

var MAX_MINUTES = 60 * 24 * 60;   // 60 суток — всё больше считаем ошибкой

// ═══════════════════════════════════════════════════════════════════════════
// ТОЧКА ВХОДА
// ═══════════════════════════════════════════════════════════════════════════
function trigger(source, value, variables, options, context) {
  try {
    var v = (typeof value === "object" && value !== null) ? value.value : value;
    var present = (v === 1 || v === true || v === "1");

    var svc  = source.getService();
    var dist = svc.getCharacteristic(HC.C_Distance);
    if (!dist) {
      console.error("[Присутствие-время] В сервисе нет характеристики C_Distance");
      return;
    }
    if (!variables.label) variables.label = makeLabel(svc);

    if (present) {
      if (!isValidStart(variables.start)) {
        if (variables.lastPresence == null) {
          // Первый вызов после перезапуска хаба/сценария при уже присутствующем человеке:
          // восстанавливаем начало отсчёта из текущего значения «Дистанции»
          var mins = decodeTime(dist.getValue());
          variables.start = Date.now() - mins * 60000;
          if (options.logEnabled) console.info("[Присутствие-время] " + variables.label + ": восстановлено " + mins + " мин");
        } else {
          variables.start = Date.now();
          if (options.logEnabled) console.info("[Присутствие-время] " + variables.label + ": пришёл(ла) домой");
        }
      }
      startCron(dist, variables);
      updateValue(dist, variables);
    } else {
      stopCron(variables);
      if (isValidStart(variables.start) && options.logEnabled) {
        var total = Math.floor((Date.now() - variables.start) / 60000);
        console.info("[Присутствие-время] " + variables.label + ": ушёл(ла), был(а) дома " + formatHuman(total));
      }
      variables.start = undefined;
      if (options.resetOnLeave) writeValue(dist, 0, variables);
    }
    variables.lastPresence = present ? 1 : 0;
  } catch (e) {
    console.error("[Присутствие-время] trigger: " + e.message);
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// КРОН — раз в минуту, только пока человек дома
// ═══════════════════════════════════════════════════════════════════════════
function startCron(dist, variables) {
  if (variables.cron) return;
  variables.cron = Cron.schedule("0 * * * * *", function () {
    try { updateValue(dist, variables); }
    catch (e) { console.error("[Присутствие-время] cron: " + e.message); }
  });
}

function stopCron(variables) {
  if (variables.cron) { variables.cron.clear(); variables.cron = undefined; }
}

// ═══════════════════════════════════════════════════════════════════════════
// РАСЧЁТ И ЗАПИСЬ
// ═══════════════════════════════════════════════════════════════════════════
function updateValue(dist, variables) {
  if (!isValidStart(variables.start)) return;
  var mins = Math.floor((Date.now() - variables.start) / 60000);
  if (mins < 0) mins = 0;
  writeValue(dist, encodeTime(mins), variables);
}

function writeValue(dist, val, variables) {
  if (val === undefined || val === null || isNaN(val)) return;
  if (variables.lastWritten != null && variables.lastWritten === val) return;
  dist.setValue(val);
  variables.lastWritten = val;
}

// минуты → Ч.ММ (165 → 2.45)
function encodeTime(mins) {
  var h = Math.floor(mins / 60);
  var m = mins % 60;
  return Math.round(h * 100 + m) / 100;
}

// Ч.ММ → минуты (2.45 → 165)
function decodeTime(d) {
  d = Number(d);
  if (!d || isNaN(d) || d < 0) return 0;
  var h = Math.floor(d + 0.000001);
  var m = Math.round((d - h) * 100);
  if (m > 59) m = 59;
  var mins = h * 60 + m;
  if (mins > MAX_MINUTES) return 0;   // мусор в характеристике — начинаем с нуля
  return mins;
}

// Платформа может отдавать null вместо undefined — проверяем, что start реальная метка времени
function isValidStart(t) {
  if (t == null || typeof t !== "number" || isNaN(t)) return false;
  var age = Date.now() - t;
  return age >= 0 && age <= MAX_MINUTES * 60000;
}

function formatHuman(mins) {
  var h = Math.floor(mins / 60);
  var m = mins % 60;
  return (h > 0 ? h + " ч " : "") + m + " мин";
}

function makeLabel(svc) {
  var s = "?";
  try { s = svc.getAccessory().getName() + " / " + svc.getName(); } catch (e) {
    try { s = svc.getName(); } catch (e2) {}
  }
  return s;
}
